// UsdAttribute::Get(&value, time): undefined when the attribute is invalid or
// has no value.
function _get(attr: Attribute | undefined, time: number | UsdTimeCode): unknown {
  return attr?.getValueAtTime(time)
}

// TfStringify(UsdTimeCode): "DEFAULT" for the default time code.
function _stringifyTime(time: number | UsdTimeCode): string {
  const t = typeof time === 'number' ? new UsdTimeCode(time) : time
  return t.isDefault() ? 'DEFAULT' : String(t.GetValue())
}

// UsdAttribute::GetPath() of a possibly invalid attribute handle.
function _attrPath(attr: Attribute | undefined, prim: Prim, name: string): string {
  return attr?.getPath() ?? `${prim.path}.${name}`
}

function _vec3(v: unknown): number[] {
  if (v instanceof GfVec) return [...v.data]
  return Array.from(v as ArrayLike<number>)
}

function _floatArray(v: unknown): number[] {
  const arr = v instanceof VtArray ? v.toArray() : Array.from(v as ArrayLike<number>)
  return (arr as number[]).map((x) => Math.fround(x))
}

// The bounding-volume target lookup of distanceHeuristic.cpp:221-237: the
// target prim must be a Boundable whose ComputeExtent yields 2 points; the
// GfRange3f built from them is returned (it may still be empty).
function _computeBoundableExtent(
  prim: Prim, targetPath: string, time: number | UsdTimeCode,
): Range3d | null {
  const targetPrim = prim.getPrimAtPath(targetPath)
  if (!targetPrim || !targetPrim.isA('Boundable')) return null
  const t = typeof time === 'number' ? new UsdTimeCode(time) : time
  const vtExtent = Boundable.computeExtent(targetPrim, t.isDefault() ? undefined : t.GetValue())
  if (vtExtent === null || vtExtent.length !== 2) return null
  // GfRange3f(vtExtent[0], vtExtent[1]) assigned to a GfRange3d.
  return new Range3d(new Vec3d(new Vec3f(vtExtent[0])), new Vec3d(new Vec3f(vtExtent[1])))
}

